-- The grades retired on a sheet, each at most once. A retired grade cannot be chosen for a person
-- (added, edited, quick-added or imported); people already on it keep it. Not dated.
CREATE TABLE retired_grade (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade      VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    retired_on DATE         NOT NULL,
    CONSTRAINT retired_grade_unique UNIQUE (sheet_id, grade)
);
EOF
d=src/main/java/net/officefloor/hq/app/grade; mkdir -p $d
cat > $d/RetiredGrade.java <<'EOF'
package net.officefloor.hq.app.grade;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A grade retired on a sheet: it can no longer be chosen for a person; those on it keep it. */
@Entity
@Table(name = "retired_grade")
public class RetiredGrade {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(nullable = false)
    private String grade;

    /** The sheet's today when the grade was retired. */
    @Column(name = "retired_on", nullable = false)
    private LocalDate retiredOn;

